/**
 * F-182 opening — the per-spec-point drill census over a served course bundle.
 *
 * Spec of record: docs/F182-DRILL-SURFACE-PLAN.md (preregistered with this
 * implementation per the #216/#225/#229/#232/DC-4 pattern); the product spec
 * is the Kognity dossier v1.1 Deep Dive D §8.5 row 1 (tracker F-182).
 *
 * Opening scope is READ-ONLY over the served content plane: pure functions,
 * no endpoints, no DB, no writes. The census of record artifact
 * (census-of-record.json, same directory) is generated by
 * apps/api/scripts/f182_drill_census.ts and pinned by
 * apps/api/test/drill/draw.test.ts — it cannot drift silently.
 *
 * Determinism law: computeCensus is a pure function of (sets, nodes); the
 * committed artifact carries no wall-clock fields.
 */

/** The served per-set shape of apps/hub/content/<course>/questions.json (the fields the drill reads). */
export interface BundlePart {
  id: string;
  order: number;
  marks: number;
  questionType?: string | null;
  specPointCodes?: string[] | null;
}

export interface BundleQuestion {
  id: string;
  parts: BundlePart[];
}

export interface BundleSet {
  slug: string;
  questions: BundleQuestion[];
}

/** The curriculum.json node shape (the fields the census reads). */
export interface CurriculumNode {
  code: string;
  family: string;
}

/** The serving plane a set rides on. */
export type Plane = "official" | "topic";

/** Official-plane set slugs embed the paper code (ADR-037 per-paper topic law). */
export const OFFICIAL_SLUG_PREFIX = "official-4ch1-";

/** A draw is offered at an address only when at least this many parts are anchored (fail-closed floor). */
export const DRILLABLE_FLOOR = 5;

export function planeOf(setSlug: string): Plane {
  return setSlug.startsWith(OFFICIAL_SLUG_PREFIX) ? "official" : "topic";
}

/** A drillable part: carries at least one spec-point code (the anchor law). */
export interface DrillPart {
  readonly partId: string;
  readonly questionId: string;
  readonly setId: string;
  readonly plane: Plane;
  readonly order: number;
  readonly marks: number;
  readonly specPointCodes: readonly string[];
}

/**
 * Anchor law: parts with an empty specPointCodes list never enter the drill
 * bank (F-182: "ships only where spec-tagging exists — unmapped content stays
 * out"). One flat pass over every set/question/part of the bundle.
 */
export function collectParts(sets: readonly BundleSet[]): DrillPart[] {
  const out: DrillPart[] = [];
  for (const set of sets) {
    const plane = planeOf(set.slug);
    for (const question of set.questions) {
      for (const part of question.parts) {
        const codes = part.specPointCodes ?? [];
        if (codes.length === 0) continue;
        out.push({
          partId: part.id,
          questionId: question.id,
          setId: set.slug,
          plane,
          order: part.order,
          marks: part.marks,
          specPointCodes: [...codes],
        });
      }
    }
  }
  return out;
}

export interface AddressRow {
  readonly code: string;
  /** Parts anchored to this address from the official past-paper plane. */
  readonly official: number;
  /** Parts anchored from the topic plane (the bundle-authored SME bank). */
  readonly topic: number;
  readonly combined: number;
  /** combined >= DRILLABLE_FLOOR — the surface offers a drill here. */
  readonly drillable: boolean;
}

export interface DrillCensus {
  readonly courseSlug: string;
  /** The bundle file of record the census was computed over (repo-relative). */
  readonly source: string;
  readonly spine: {
    readonly subject: string;
    readonly specPointNodes: number;
  };
  readonly bundle: {
    readonly sets: number;
    readonly officialSets: number;
    readonly topicSets: number;
    readonly questions: number;
    readonly parts: number;
  };
  readonly eligibility: {
    readonly officialParts: number;
    readonly topicParts: number;
    readonly eligibleParts: number;
    readonly partsWithoutCodes: number;
    /** Questions where NO part carries a code (the terminal unmapped of record). */
    readonly unmappedQuestions: readonly string[];
  };
  readonly coverage: {
    /** Spine SPEC_POINT addresses total (the "% spec points drill-covered" denominator). */
    readonly specPointAddresses: number;
    /** Addresses with >= 1 anchored part. */
    readonly covered: number;
    /** Addresses at or above the drillable floor. */
    readonly drillable: number;
    /** Addresses with 1..floor-1 anchored parts (offered once the corpus grows). */
    readonly thin: number;
    /** Spine addresses with zero anchored parts. */
    readonly uncovered: number;
  };
  /** Every spine SPEC_POINT address, sorted by code (zeros included). */
  readonly addresses: readonly AddressRow[];
}

/**
 * The per-spec-point census: walk the bundle, count part x code anchorings per
 * plane, validate every code against the curriculum spine, and project spine
 * coverage. Multi-code parts count once per address (an anchoring, not a
 * partition) — this is the unit difference vs the wave receipts' label
 * decisions (disclosed in the plan doc).
 */
export function computeCensus(
  courseSlug: string,
  source: string,
  sets: readonly BundleSet[],
  nodes: readonly CurriculumNode[],
): DrillCensus {
  const specPointCodes = nodes
    .filter((n) => n.family === "SPEC_POINT")
    .map((n) => n.code)
    .sort();
  const spineSet = new Set(specPointCodes);

  const officialByCode = new Map<string, number>();
  const topicByCode = new Map<string, number>();
  let questions = 0;
  let parts = 0;
  let officialSets = 0;
  let topicSets = 0;
  let officialEligible = 0;
  let topicEligible = 0;
  let partsWithoutCodes = 0;
  const unmappedQuestions: string[] = [];

  for (const set of sets) {
    const plane = planeOf(set.slug);
    if (plane === "official") officialSets += 1;
    else topicSets += 1;
    for (const question of set.questions) {
      questions += 1;
      let questionHasCodes = false;
      for (const part of question.parts) {
        parts += 1;
        const codes = part.specPointCodes ?? [];
        if (codes.length === 0) {
          partsWithoutCodes += 1;
          continue;
        }
        questionHasCodes = true;
        if (plane === "official") officialEligible += 1;
        else topicEligible += 1;
        const target = plane === "official" ? officialByCode : topicByCode;
        for (const code of codes) {
          if (!spineSet.has(code)) {
            throw new Error(`spec code outside the spine: ${code} (part ${part.id})`);
          }
          target.set(code, (target.get(code) ?? 0) + 1);
        }
      }
      if (!questionHasCodes) unmappedQuestions.push(`${set.slug}:${question.id}`);
    }
  }

  const addresses: AddressRow[] = specPointCodes.map((code) => {
    const official = officialByCode.get(code) ?? 0;
    const topic = topicByCode.get(code) ?? 0;
    const combined = official + topic;
    return { code, official, topic, combined, drillable: combined >= DRILLABLE_FLOOR };
  });

  const covered = addresses.filter((a) => a.combined > 0).length;
  const drillable = addresses.filter((a) => a.drillable).length;
  const thin = addresses.filter((a) => a.combined > 0 && !a.drillable).length;

  return {
    courseSlug,
    source,
    spine: { subject: "4CH1 Chemistry (Pearson Edexcel IGCSE, 2017 Issue 3)", specPointNodes: specPointCodes.length },
    bundle: { sets: sets.length, officialSets, topicSets, questions, parts },
    eligibility: {
      officialParts: officialEligible,
      topicParts: topicEligible,
      eligibleParts: officialEligible + topicEligible,
      partsWithoutCodes,
      unmappedQuestions: [...unmappedQuestions].sort(),
    },
    coverage: {
      specPointAddresses: specPointCodes.length,
      covered,
      drillable,
      thin,
      uncovered: specPointCodes.length - covered,
    },
    addresses,
  };
}
